#![cfg(feature = "snapgene")]

//! Committed synthetic fixture coverage for the SnapGene reader.
//!
//! These are the fixtures generated by the conformance crate (task-11), never
//! corpus copies. Each file is imported and its documented outcome is asserted;
//! the list of expected error stems mirrors testdata/README.md section 5.2.

use std::path::{Path, PathBuf};

use sequon_io::api::{Format, ImportOptions};

fn fixture_directory() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("testdata")
        .join("snapgene")
}

fn import(bytes: &[u8]) -> sequon_io::api::ImportResult {
    let options = ImportOptions {
        format: Some(Format::Snapgene),
        ..ImportOptions::default()
    };
    sequon_io::import(bytes, &options)
}

fn expected_error(stem: &str) -> Option<&'static str> {
    Some(match stem {
        "070-truncated" => "DNA_TRUNCATED_PACKET",
        "080-lzma-bomb" => "DNA_DECOMPRESSION_LIMIT",
        "090-deep-xml" => "DNA_XML_DEPTH_EXCEEDED",
        "110-both-dna-packets" => "DNA_DUPLICATE_DNA_PACKET",
        "120-no-dna-packet" => "DNA_NO_DNA_PACKET",
        "130-missing-name" => "RECORD_REQUIRED_FIELD_MISSING",
        "131-rna-seq-type" => "DNA_UNKNOWN_SEQ_TYPE",
        "132-unknown-seq-type" => "DNA_UNKNOWN_SEQ_TYPE",
        _ => return None,
    })
}

fn has_diagnostic(outcome: &sequon_io::api::ImportOutcome, code: &str) -> bool {
    outcome
        .report
        .diagnostics
        .iter()
        .any(|diagnostic| diagnostic.code == code)
}

#[test]
fn every_committed_fixture_has_its_documented_outcome() {
    let directory = fixture_directory();
    if !directory.is_dir() {
        eprintln!("testdata/snapgene is not present; fixture coverage skipped");
        return;
    }
    let mut fixtures: Vec<PathBuf> = std::fs::read_dir(&directory)
        .expect("read fixture directory")
        .filter_map(|entry| entry.ok())
        .map(|entry| entry.path())
        .filter(|path| path.extension().is_some_and(|extension| extension == "dna"))
        .collect();
    fixtures.sort();
    assert!(
        fixtures.len() >= 28,
        "expected the committed fixture catalogue, found {} files",
        fixtures.len()
    );
    for path in fixtures {
        let stem = path
            .file_stem()
            .and_then(|stem| stem.to_str())
            .expect("fixture stem");
        let bytes = std::fs::read(&path).expect("read fixture");
        let outcome = import(&bytes);
        match expected_error(stem) {
            Some(code) => {
                let error = outcome.expect_err(&format!("fixture {stem} must fail with {code}"));
                assert_eq!(error.code(), code, "fixture {stem} error code");
            }
            None => {
                let outcome =
                    outcome.unwrap_or_else(|error| panic!("fixture {stem} must import: {error}"));
                assert_eq!(outcome.records.len(), 1, "fixture {stem} record count");
                outcome.records[0]
                    .validate()
                    .unwrap_or_else(|error| panic!("fixture {stem} record invalid: {error}"));
                sequon_algo::verify_digests(&outcome.records[0])
                    .unwrap_or_else(|error| panic!("fixture {stem} digests: {error}"));
                assert!(
                    outcome
                        .report
                        .diagnostics
                        .iter()
                        .all(|diagnostic| diagnostic.severity != sequon_io::report::Severity::Error),
                    "fixture {stem} returned an error-severity diagnostic"
                );
            }
        }
    }
}

#[test]
fn documented_success_fixtures_carry_their_expected_evidence() {
    let directory = fixture_directory();
    if !directory.is_dir() {
        eprintln!("testdata/snapgene is not present; fixture coverage skipped");
        return;
    }
    let load = |stem: &str| -> Vec<u8> {
        std::fs::read(directory.join(format!("{stem}.dna"))).expect("read fixture")
    };

    let outcome = import(&load("001-linear-uncompressed")).expect("001");
    assert_eq!(outcome.records[0].topology, sequon_model::Topology::Linear);

    let outcome = import(&load("003-type0-observed-flags")).expect("003");
    assert_eq!(
        outcome.records[0].topology,
        sequon_model::Topology::Circular
    );
    assert_eq!(outcome.records[0].name, "sequon-fixture-003");

    let outcome = import(&load("005-unknown-flag-bits")).expect("005");
    assert!(has_diagnostic(&outcome, "DNA_TOPOLOGY_FLAG_UNKNOWN"));

    let outcome = import(&load("010-history-v14")).expect("010");
    assert!(has_diagnostic(&outcome, "DNA_HISTORY_PRESERVED_RAW"));
    assert_eq!(outcome.report.preserved.len(), 1);

    let outcome = import(&load("011-history-v17")).expect("011");
    assert!(has_diagnostic(&outcome, "DNA_HISTORY_PRESERVED_RAW"));
    assert_eq!(outcome.report.preserved.len(), 1);

    let outcome = import(&load("012-version15-no-history")).expect("012");
    assert!(!has_diagnostic(&outcome, "DNA_HISTORY_PRESERVED_RAW"));
    assert!(!has_diagnostic(&outcome, "DNA_HISTORY_DECODE_FAILED"));

    let outcome = import(&load("020-features-multisegment")).expect("020");
    let feature = &outcome.records[0].features[0];
    assert_eq!(feature.location.operator, "join");
    assert_eq!(feature.location.strand, -1);

    let outcome = import(&load("030-primers")).expect("030");
    assert_eq!(outcome.records[0].features[0].key, "primer_bind");

    let outcome = import(&load("040-notes-properties")).expect("040");
    let snapgene = outcome.records[0]
        .extras
        .get("snapgene")
        .and_then(sequon_model::JsonValue::as_object)
        .expect("extras.snapgene");
    assert!(snapgene.get("notes").is_some());
    assert!(snapgene.get("properties").is_some());

    let outcome = import(&load("050-traces")).expect("050");
    assert!(has_diagnostic(&outcome, "DNA_PACKET_IGNORED"));
    assert_eq!(outcome.report.preserved.len(), 1);

    let outcome = import(&load("060-unknown-packet")).expect("060");
    assert!(has_diagnostic(&outcome, "DNA_UNKNOWN_PACKET"));
    assert_eq!(outcome.report.preserved.len(), 1);

    let outcome = import(&load("100-unicode-notes")).expect("100");
    assert!(has_diagnostic(&outcome, "DNA_SEQUENCE_NORMALIZED"));

    for stem in ["061-restriction-sites", "062-enzyme-settings"] {
        let outcome = import(&load(stem)).expect(stem);
        assert!(has_diagnostic(&outcome, "DNA_PACKET_IGNORED"), "{stem}");
        assert_eq!(outcome.report.preserved.len(), 1, "{stem}");
    }

    let outcome = import(&load("041-name-custom-map-label")).expect("041");
    assert_eq!(outcome.records[0].name, "sequon-custom-label");

    let outcome = import(&load("042-name-precedence")).expect("042");
    assert_eq!(outcome.records[0].name, "SYN0001");
}

#[test]
fn fixture_directory_path_is_the_committed_one() {
    let directory = fixture_directory();
    assert!(Path::new(&directory).ends_with("testdata/snapgene"));
}
